import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1785861127000}'),i={name:"guide/faq.md"};function l(n,a,h,s,d,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="安装后还需要做什么配置吗" tabindex="-1">安装后还需要做什么配置吗？ <a class="header-anchor" href="#安装后还需要做什么配置吗" aria-label="Permalink to &quot;安装后还需要做什么配置吗？&quot;">​</a></h2><p>不需要。默认配置已启用缓存清理、后台压制、垃圾回收与空文件夹清理，重启后即按计划在后台运行。安装 CZeroX 是为了查看运行状态与调整设置，并非必需。</p><h2 id="修改设置后需要重启吗" tabindex="-1">修改设置后需要重启吗？ <a class="header-anchor" href="#修改设置后需要重启吗" aria-label="Permalink to &quot;修改设置后需要重启吗？&quot;">​</a></h2><p>不需要，保存即生效。</p><h2 id="支持哪些-root-方案" tabindex="-1">支持哪些 Root 方案？ <a class="header-anchor" href="#支持哪些-root-方案" aria-label="Permalink to &quot;支持哪些 Root 方案？&quot;">​</a></h2><p>Magisk、KernelSU 与 APatch 均可。设备需为 Android 9 及以上的 <code>arm64</code> 机型。</p><h2 id="可以不安装-czerox-吗" tabindex="-1">可以不安装 CZeroX 吗？ <a class="header-anchor" href="#可以不安装-czerox-吗" aria-label="Permalink to &quot;可以不安装 CZeroX 吗？&quot;">​</a></h2><p>可以，模块能够独立运行。但此时没有图形界面，调整设置需手动编辑配置文件，不推荐这样使用。</p><h2 id="清理会误删数据吗" tabindex="-1">清理会误删数据吗？ <a class="header-anchor" href="#清理会误删数据吗" aria-label="Permalink to &quot;清理会误删数据吗？&quot;">​</a></h2><p>清理仅针对缓存与残留目录，并有两层保护：</p><ul><li><strong>时序屏障</strong> —— 默认只处理 3 天以前的文件，近期产生的数据不受影响。可调大该值以更保守。</li><li><strong>回收站</strong> —— 清理不做真正的删除，而是先将文件移入回收站保留 7 天，期间可完整恢复。</li></ul><h2 id="误删的文件如何恢复" tabindex="-1">误删的文件如何恢复？ <a class="header-anchor" href="#误删的文件如何恢复" aria-label="Permalink to &quot;误删的文件如何恢复？&quot;">​</a></h2><p>在 CZeroX 的<strong>回收站</strong>中找到对应记录并执行恢复，文件会原样移回原始位置。超过保留期的记录将被自动清除，不再可恢复。</p><p>保留期可在回收站设置中调整，代价是占用更多存储空间。</p><h2 id="设备不是-f2fs-文件系统-可以使用吗" tabindex="-1">设备不是 F2FS 文件系统，可以使用吗？ <a class="header-anchor" href="#设备不是-f2fs-文件系统-可以使用吗" aria-label="Permalink to &quot;设备不是 F2FS 文件系统，可以使用吗？&quot;">​</a></h2><p>可以。除 <strong>F2FS 垃圾回收</strong>外，其余功能均不依赖文件系统类型。非 F2FS 设备将该功能关闭即可。</p><h2 id="垃圾回收似乎从未执行" tabindex="-1">垃圾回收似乎从未执行？ <a class="header-anchor" href="#垃圾回收似乎从未执行" aria-label="Permalink to &quot;垃圾回收似乎从未执行？&quot;">​</a></h2><p>这属于正常现象。垃圾回收并非到点必然执行，需同时满足以下条件：</p><ul><li>存储确有回收必要（空间充裕时无需回收）；</li><li>距上次回收已间隔足够时间；</li><li>屏幕处于熄灭状态；</li><li>电量充足且电池温度正常。</li></ul><p>因此，长期观察不到它执行，通常说明设备状态良好。如需确认，可开启日志，其中会记录本轮被哪一项条件跳过。</p><h2 id="fstrim-与垃圾回收有何区别" tabindex="-1">fstrim 与垃圾回收有何区别？ <a class="header-anchor" href="#fstrim-与垃圾回收有何区别" aria-label="Permalink to &quot;fstrim 与垃圾回收有何区别？&quot;">​</a></h2><p><strong>垃圾回收</strong>整理设备内部的文件系统碎片；<strong>fstrim</strong> 则将已释放的空间告知存储器件，使其自身的回收机制有据可依。两者互补，默认均已启用，无需额外配置。</p><h2 id="精细化压制与后台压制有何区别" tabindex="-1">精细化压制与后台压制有何区别？ <a class="header-anchor" href="#精细化压制与后台压制有何区别" aria-label="Permalink to &quot;精细化压制与后台压制有何区别？&quot;">​</a></h2><ul><li><strong>后台压制</strong> —— 直接结束后台进程，立即释放内存，代价是下次启动需重新加载。</li><li><strong>精细化压制</strong> —— 挂起应用而不结束进程，停止占用 CPU 的同时完整保留运行状态，切回时即时恢复。</li></ul><p>前者适用于希望彻底释放资源的场景，后者适用于希望保留应用现场的场景，两者可同时启用。精细化压制需要 Android 12 及以上版本。</p><h2 id="重装或升级模块会丢失设置吗" tabindex="-1">重装或升级模块会丢失设置吗？ <a class="header-anchor" href="#重装或升级模块会丢失设置吗" aria-label="Permalink to &quot;重装或升级模块会丢失设置吗？&quot;">​</a></h2><p>不会。刷入时选择<strong>继承</strong>，已有的规则、白名单与调整过的选项均会保留，新版本新增的选项会自动补齐。</p><h2 id="卸载后会残留文件吗" tabindex="-1">卸载后会残留文件吗？ <a class="header-anchor" href="#卸载后会残留文件吗" aria-label="Permalink to &quot;卸载后会残留文件吗？&quot;">​</a></h2><p>不会。在 Root 管理器中移除模块并重启，模块目录连同统计与日志一并清除。回收站位于内置存储的 <code>Recycle</code> 文件夹，如需彻底清理可手动删除。</p><h2 id="日志在哪里查看" tabindex="-1">日志在哪里查看？ <a class="header-anchor" href="#日志在哪里查看" aria-label="Permalink to &quot;日志在哪里查看？&quot;">​</a></h2><p>在 CZeroX 中开启日志后，日志保存于模块目录的 <code>log</code> 文件夹，仅保留当天记录。反馈问题时附上日志有助于快速定位。</p><h2 id="如何反馈问题" tabindex="-1">如何反馈问题？ <a class="header-anchor" href="#如何反馈问题" aria-label="Permalink to &quot;如何反馈问题？&quot;">​</a></h2><p>请通过 <a href="https://github.com/Xocio/CZero/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 提交，或加入<a href="https://t.me/+lwNKCHw_NktjODRh" target="_blank" rel="noreferrer">交流群</a>。</p><p>各项功能的详细说明见<a href="/guide/features">功能详解</a>，逐字段的配置说明见<a href="/guide/configuration">配置参考</a>。</p>',35)])])}const f=e(i,[["render",l]]);export{p as __pageData,f as default};
